var a=`0833-palak-paneer`;var i=`world-0833`;var t=`IN`;var s=`south-asia`;var r=4;var o=33;var h={en:`Palak Paneer`,ua:`Палак панір`};var g={en:`Palak Paneer is a India dish made with spinach, serrano pepper, yellow onion, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Палак панір, страва кухні країни Індія. Основні складники: шпинат, перець серрано, жовта цибуля, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Separate and blanch the leaves in hot water for about 3 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 3 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:3,i:[[`spinach`,600,`g`],[`water`,950,`ml`]]},{en:`Blend the blanched, drained spinach with chile and ginger until smooth; keep the vivid green puree for the paneer sauce.`,ua:`Подрібніть бланшований обсушений шпинат із перцем та імбиром до гладкого пюре; збережіть його для зеленого соусу до паніру.`,t:[`mixing`],m:7,i:[[`serrano-pepper`,2,`pcs`],[`ground-ginger`,15,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`ghee`,55,`g`],[`yellow-onion`,200,`g`],[`tomato`,250,`g`],[`garam-masala`,6,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 10 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 10 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:10,i:[[`paneer`,460,`g`],[`heavy-cream`,90,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`kasuri-methi`,3,`g`]]}];var d={slug:a,id:i,country:`IN`,region:s,servings:4,minutes:33,title:h,text:g,steps:l};export{t as country,d as default,i as id,o as minutes,s as region,r as servings,a as slug,l as steps,g as text,h as title};